/* ---------- glossary ---------- */
const GL=[
 ["Big Data",1,"Any data that is expensive to manage and hard to extract value from (Michael Franklin)."],
 ["Big data analytics",1,"Examining large data sets to uncover hidden patterns, unknown correlations, market trends and customer preferences."],
 ["Volume",1,"Data at rest: terabytes to exabytes of existing data to process."],
 ["Velocity",1,"Data in motion: streaming data, milliseconds to seconds to respond."],
 ["Variety",1,"Data in many forms: structured, unstructured, text, multimedia."],
 ["Veracity",1,"Data in doubt: inconsistency, incompleteness, ambiguities, latency, deception, model approximations. Added by IBM (4Vs)."],
 ["Value",1,"Demchenko's 5th V: hypothetical, correlations, events, statistical."],
 ["Visibility",1,"Microsoft's 6th V. Named on the slide but not described."],
 ["Four M's",1,"Make Me More Money: the business goal organisations forget when adopting big data."],
 ["Analytics stack",1,"Five layers: infrastructure platforms, big data platforms, analytics platforms, analytics tools, analytics solutions."],
 ["Data Science",1,"Collection, preparation, analysis, visualization, management and preservation of large collections of information."],
 ["Machine Learning",1,"A type of AI that lets computers learn without being explicitly programmed."],
 ["Dataset",1,"A collection of related data whose members share the same attributes, e.g. tweets in a flat file or rows in a CSV."],
 ["NoSQL",1,"Storage and retrieval modelled other than as relational tables: non-relational, schema-free, replicated, horizontally scalable, fast key-value access."],
 ["Cloud Computing",1,"Using remote servers hosted on the internet to store, manage and process data instead of a local server or PC."],
 ["Structured data",2,"Defined data type, format and structure: transaction data, RDBMS, CSV, spreadsheets."],
 ["Semi-structured data",2,"Textual files with a discernible pattern that enables parsing, e.g. self-describing XML."],
 ["Quasi-structured data",2,"Between structured and unstructured; irregular patterns needing specialised parsing, e.g. clickstream, web logs, email headers, IoT streams."],
 ["Unstructured data",2,"No predefined data model or schema: text documents, PDFs, images, video."],
 ["Hadoop",2,"Software framework for distributed processing of large datasets across large clusters; open-source implementation of Google MapReduce."],
 ["Computer cluster",2,"Loosely or tightly connected computers working together so they can be viewed as a single system."],
 ["Data locality",2,"Running computation on the node that already stores the data, to avoid network traffic."],
 ["Shared nothing",2,"Architecture where nodes talk to each other as little as possible; developers don't write inter-node code."],
 ["HDFS",2,"Hadoop Distributed File System: Java-based, scalable, fault-tolerant storage on commodity hardware."],
 ["NameNode",2,"HDFS master. Holds metadata only: namespace tree and block → DataNode map, all in RAM."],
 ["DataNode",2,"HDFS slave that stores actual blocks on its local file system and sends heartbeats."],
 ["Secondary NameNode",2,"Shown in a diagram but not explained. Periodically merges the edit log into the fsimage (checkpointing); not a live backup."],
 ["Block",2,"A chunk of a file, typically 128 MB (64 MB in Hadoop 1), replicated independently across DataNodes."],
 ["Replication",2,"Storing each block on several DataNodes (3 in the slide example) for availability and reliability."],
 ["Heartbeat",2,"Periodic DataNode signal to the NameNode. The NameNode sends instructions only in replies to heartbeats."],
 ["Inode",2,"NameNode record for a file or directory: permissions, modification and access times, namespace and disk-space quotas."],
 ["Rack",2,"A group of DataNodes; blocks are replicated across racks (Rack 1, Rack 2)."],
 ["MapReduce",2,"Method for distributing a task across nodes in two phases, Map and Reduce, each node processing local data."],
 ["Mapper",2,"Reads key/value pairs and outputs zero or more intermediate key/value pairs. Line input key = byte offset."],
 ["Reducer",2,"Receives all values for a key in sorted order and outputs final key/value pairs to HDFS."],
 ["Shuffle and sort",2,"Grouping all intermediate values by key and delivering them to Reducers in sorted key order."],
 ["Combiner",2,"Local pre-summing in the mapper, e.g. BAB → (B,2). Shown in the five-step diagram but not named."],
 ["Five-step model",2,"Splitting, Mapping (distribution), Shuffling and sorting, Reducing (parallelizing), Aggregating."],
 ["InputFormat",2,"Divides the input into ranges; one map task is created per range."],
 ["JobTracker",2,"MRv1 master: resource management, tracking resources, job life-cycle management."],
 ["TaskTracker",2,"MRv1 per-node slave: launches and tears down tasks, reports status periodically."],
 ["YARN",2,"Yet Another Resource Negotiator: resource management layer that supports non-MapReduce workloads."],
 ["ResourceManager",2,"YARN's global ultimate authority arbitrating resources among all applications."],
 ["Scheduler",2,"Pluggable part of the ResourceManager that allocates resources subject to capacities, queues, etc."],
 ["NodeManager",2,"YARN per-machine agent responsible for containers and reporting their resource usage."],
 ["ApplicationMaster",2,"YARN per-application library that negotiates resources and works with NodeManagers to run tasks."],
 ["Container",2,"Abstract bundle of resources (memory, CPU, disk, network) in which a task runs."],
 ["DAG",2,"Directed acyclic graph. A YARN application is a single job or a DAG of jobs."],
 ["Hive",2,"Data warehouse with an SQL-like interface; converts SQL into MapReduce jobs."],
 ["Pig",2,"Platform using the Pig Latin language, compiled to MapReduce."],
 ["Spark",2,"In-memory processing engine for fast iterative analytics like clustering and classification."],
 ["HBase",2,"Column-oriented NoSQL store with random real-time read/write access."],
 ["Storm",2,"Distributed real-time computation over large data streams."],
 ["Kafka",2,"Distributed event streaming platform for real-time pipelines."],
 ["Slider",2,"Deployed existing distributed apps on YARN; retired by Apache in 2018."],
 ["Solr",2,"Scalable open-source enterprise search built on Apache Lucene."],
 ["Tez",2,"Framework for high-performance batch and interactive processing; speeds up Hive and Pig."],
 ["Mahout",2,"Distributed linear algebra framework and Scala DSL for scalable machine learning."],
 ["Accumulo",2,"Sorted distributed key-value store based on Google Bigtable, with cell-level security."],
 ["HCatalog",2,"Table and storage management layer shared by Pig, Hive and MapReduce."],
 ["Flume",2,"Collects, aggregates and moves high-volume streaming and log data into Hadoop."],
 ["Sqoop",2,"Bulk transfer of structured data between RDBMS/NoSQL and Hadoop."],
 ["Knox",2,"Perimeter security gateway and reverse proxy for Hadoop clusters."],
 ["Ranger",2,"Centralized authorization and fine-grained access control (FGAC)."],
 ["Ambari",2,"Cluster management and provisioning tool."],
 ["Oozie",2,"Workflow scheduler and coordination engine."],
 ["ZooKeeper",2,"Distributed coordination service."],
 ["Hive (Ch 3)",3,"Data warehouse infrastructure tool to process structured data in Hadoop; resides on top of Hadoop to summarize big data and make querying easy."],
 ["HiveQL",3,"Hive's SQL-like query language, also called HQL or QL. Lets users query without Java or Hadoop APIs."],
 ["Data warehouse",3,"A system for storing and analysing large volumes of historical data, rather than running live transactions."],
 ["ETL",3,"Extract, Transform, Load. Hive provides tools to enable easy data ETL."],
 ["CLI",3,"Command Line Interface: Hive's shell for interactive queries."],
 ["HWI",3,"Hive Web Interface: browser-based Hive UI (removed in Hive 2.2)."],
 ["Thrift Server",3,"Accepts requests from Thrift, JDBC and ODBC clients and passes them to the Driver (today: HiveServer2)."],
 ["JDBC / ODBC",3,"Standard database connection APIs. Hive provides JDBC and ODBC drivers so apps and BI tools can query it."],
 ["Shell",3,"Hive component that allows interactive queries."],
 ["Driver (Hive)",3,"Hive component handling session handles, fetch and execute; compiles, optimizes and executes queries."],
 ["Compiler",3,"Hive component that parses, plans and optimizes a query."],
 ["Execution engine",3,"Hive component that runs a DAG of stages (MapReduce, HDFS, metadata)."],
 ["Metastore",3,"Hive component storing each table's schema, location in HDFS and SerDe."],
 ["SerDe",3,"Serializer/Deserializer: converts file bytes into table rows and back. A custom SerDe lets Hive read any format."],
 ["Warehouse directory",3,"Hive's root folder in HDFS, e.g. /user/hive/warehouse. Tables are its subdirectories."],
 ["SequenceFile",3,"A Hadoop binary file format of key-value records; one of Hive's storage options."],
 ["Database (Hive)",3,"A namespace that groups tables."],
 ["Table (Hive)",3,"A schema in a namespace with typed columns (int, float, string, boolean, plus list and map)."],
 ["Partition",3,"Dividing a table into coarse-grained parts by the value of a partition column such as a date; stored as subdirectories."],
 ["Partition key",3,"The column whose values decide which folder a row is stored in."],
 ["Partition pruning",3,"Skipping folders whose partition values don't match the WHERE clause, so less data is scanned."],
 ["Bucket",3,"One of a fixed number of files a table or partition is split into, chosen by hashing a column. Used for sampling and joins."],
 ["Map Side Join",3,"A join done entirely in the map phase; possible when both tables are bucketed on the join column."],
 ["Schema on read",3,"Hive's approach: data is not verified at load time, only when queried, so loads are very fast."],
 ["Schema on write",3,"Traditional RDBMS approach: data is parsed, validated and serialized when loaded."],
 ["Primitive types",3,"BOOLEAN; TINYINT (1 byte), SMALLINT (2), INT (4), BIGINT (8); FLOAT, DOUBLE; STRING."],
 ["Struct",3,"Complex type of named fields, accessed with dot notation, e.g. info.name."],
 ["Map (type)",3,"Complex type of key-value tuples, accessed with ['element name'], e.g. marks['exam']."],
 ["Array",3,"Complex type: an indexable list accessed with [n], zero-based, e.g. subjects[0]."],
 ["OLTP",3,"Online transaction processing: many small, fast reads and writes. Hive is not designed for it."]];

